package com.huy.enterprise.alert;
import java.util.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/alerts") @RequiredArgsConstructor public class AlertController{private final AlertService service;@GetMapping public List<AlertResponse> all(){return service.all();}@GetMapping("/{id}") public AlertResponse one(@PathVariable UUID id){return service.one(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public AlertResponse create(@Valid @RequestBody CreateAlertRequest r){return service.create(r);}@PatchMapping("/{id}/status") public AlertResponse status(@PathVariable UUID id,@Valid @RequestBody UpdateAlertStatusRequest r){return service.status(id,r.status());}}
